import { Children, cloneElement, isValidElement } from "react";
import type { ReactElement, ReactNode } from "react";
import { ComparisonTableCTA } from "@/components/ComparisonTableCTA";
import { AffiliateCTA } from "@/components/AffiliateCTA";

export function GuideContent({ slug }: { slug: string }) {
  const content = guideContents[slug];
  if (!content) {
    return (
      <div className="prose prose-sm max-w-none text-muted">
        <p>この記事は現在準備中です。近日公開予定です。</p>
      </div>
    );
  }
  return <div className="space-y-6 leading-relaxed">{withDefaultPage(content, slug)}</div>;
}

type PageAwareProps = {
  page?: string;
  children?: ReactNode;
};

function DecisionBox({
  title,
  points,
  note,
}: {
  title: string;
  points: string[];
  note?: string;
}) {
  return (
    <section className="rounded-xl border border-primary/30 bg-primary/5 p-5">
      <h2 className="text-lg font-bold mb-3">{title}</h2>
      <ul className="list-disc list-inside space-y-2 text-sm text-muted">
        {points.map((point) => (
          <li key={point}>{point}</li>
        ))}
      </ul>
      {note && <p className="text-xs text-muted mt-3">{note}</p>}
    </section>
  );
}

function withDefaultPage(node: ReactNode, page: string): ReactNode {
  return Children.map(node, (child) => {
    if (!isValidElement<PageAwareProps>(child)) return child;

    const originalChildren = child.props.children;
    const nextChildren = originalChildren ? withDefaultPage(originalChildren, page) : originalChildren;
    const shouldSetPage = child.type === AffiliateCTA || child.type === ComparisonTableCTA;
    const nextProps: Partial<PageAwareProps> = {};

    if (shouldSetPage && !child.props.page) {
      nextProps.page = page;
    }
    if (nextChildren !== originalChildren) {
      nextProps.children = nextChildren;
    }

    return Object.keys(nextProps).length > 0
      ? cloneElement(child as ReactElement<PageAwareProps>, nextProps)
      : child;
  });
}

function KaigoActionBox({
  toolHref,
  toolLabel,
  boothHref,
  boothLabel,
  children,
}: {
  toolHref: string;
  toolLabel: string;
  boothHref: string;
  boothLabel: string;
  children: ReactNode;
}) {
  return (
    <section className="rounded-xl border border-primary/25 bg-primary/5 p-5">
      <h2 className="text-lg font-bold mb-3">整理した内容をそのまま使う</h2>
      <div className="text-sm text-muted leading-relaxed mb-4">{children}</div>
      <div className="flex flex-col sm:flex-row gap-3">
        <a
          href="/kaigo"
          className="inline-flex items-center justify-center rounded-full bg-primary px-5 py-2.5 text-sm font-bold text-white transition-colors hover:bg-primary-hover"
        >
          親のこと整理ナビで診断する
        </a>
        <a
          href={toolHref}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center justify-center rounded-full border border-primary/30 px-5 py-2.5 text-sm font-bold text-primary transition-colors hover:bg-primary/10"
        >
          {toolLabel}
        </a>
        <a
          href={boothHref}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center justify-center rounded-full border border-card-border px-5 py-2.5 text-sm font-bold transition-colors hover:bg-muted/10"
        >
          {boothLabel}
        </a>
      </div>
    </section>
  );
}

